import { defineComponent, VueConstructor } from 'vue';
import { inversifyContainer } from '../../inversify/container';
import { Injects } from '../../inversify/injects';
import { eventEmitter } from '../../services/event-emitter';

export default defineComponent({
    name: 'App-Root',

    data() {
        return {
            showApp: false,
            showLoadingSplash: true,
            loadingProgress: 0,
            loadingSplashOpacity: 1,
            waitingForSplashVideo: false
        };
    },
    computed: {
        appComponent() {
            return inversifyContainer.get<VueConstructor<Vue>>(Injects.AppComponent);
        }
    },
    created(): void {
        eventEmitter.on('GLOBAL_LOADING_PROGRESS', (progress) => {
            this.loadingProgress = progress * 100;
        });
        eventEmitter.on('GLOBAL_LOADING_COMPLETE', () => {
            this.showApp = true;
        });
        eventEmitter.on('SPLASH_VIDEO_ACTIVE', () => {
            this.waitingForSplashVideo = true;
        });
        eventEmitter.on('SPLASH_INTRO_COMPLETE', () => {
            this.waitingForSplashVideo = false;
            this.onLoadComplete();
        });
    },
    methods: {
        onLoadComplete(): void {
            if (this.waitingForSplashVideo) { return; }

            // Fade loading splash to 0 opacity over 0.25s then hide it
            this.loadingSplashOpacity = 0;
            setTimeout(() => {
                this.showLoadingSplash = false;
            }, 250);
        }
    }
});